import { GeneRecognitionResult, GeneRecognizer } from './scannerTypes.ts';
import { normalizeGeneGlyph } from './TesseractGeneRecognizer.ts';

interface WebViewBridge {
  postMessage(message: unknown): void;
  addEventListener(type: 'message', listener: (event: MessageEvent) => void): void;
  removeEventListener(type: 'message', listener: (event: MessageEvent) => void): void;
}

interface NativeOcrResponse {
  type: 'GENETICS_OCR_RESULT';
  requestId: number;
  texts?: string[];
  error?: string;
}

export class NativeWebViewGeneRecognizer implements GeneRecognizer {
  public readonly backend = 'windows-ocr';

  private readonly bridge: WebViewBridge;
  private readonly pending = new Map<number, (texts: string[] | null) => void>();
  private nextRequestId = 1;
  private warm = false;

  constructor(bridge: WebViewBridge) {
    this.bridge = bridge;
  }

  public static createIfSupported(): NativeWebViewGeneRecognizer | null {
    if (typeof window === 'undefined' || !(window as any).__RUSTPLUS_NATIVE_OCR__) return null;
    const bridge = (window as any).chrome?.webview as WebViewBridge | undefined;
    return bridge ? new NativeWebViewGeneRecognizer(bridge) : null;
  }

  public async warmup(): Promise<void> {
    if (this.warm) return;
    this.bridge.addEventListener('message', this.handleMessage);
    this.warm = true;
  }

  public isWarm(): boolean {
    return this.warm;
  }

  public async recognizeRow(canvas: HTMLCanvasElement): Promise<GeneRecognitionResult | null> {
    const texts = await this.recognize([canvas]);
    if (!texts) return null;

    const genes = this.extractGenes(texts[0]);
    return genes.length === 6 ? this.result(genes) : null;
  }

  public async recognizeSlots(canvases: HTMLCanvasElement[]): Promise<GeneRecognitionResult | null> {
    if (canvases.length !== 6) return null;
    const texts = await this.recognize(canvases);
    if (!texts) return null;

    const genes = texts.map(text => this.extractGenes(text)[0] || '').join('');
    return genes.length === 6 ? this.result(genes) : null;
  }

  public async terminate(): Promise<void> {
    if (this.warm) {
      this.bridge.removeEventListener('message', this.handleMessage);
    }
    this.warm = false;
    for (const resolve of this.pending.values()) resolve(null);
    this.pending.clear();
  }

  private readonly handleMessage = (event: MessageEvent): void => {
    const response = event.data as NativeOcrResponse;
    if (response?.type !== 'GENETICS_OCR_RESULT') return;

    const resolve = this.pending.get(response.requestId);
    if (!resolve) return;
    this.pending.delete(response.requestId);
    resolve(response.error ? null : response.texts || null);
  };

  private recognize(canvases: HTMLCanvasElement[]): Promise<string[] | null> {
    const requestId = this.nextRequestId++;
    return new Promise(resolve => {
      this.pending.set(requestId, resolve);
      this.bridge.postMessage({
        type: 'GENETICS_OCR_REQUEST',
        requestId,
        images: canvases.map(canvas => canvas.toDataURL('image/png'))
      });
    });
  }

  private extractGenes(text: string): string {
    return Array.from(text.toUpperCase())
      .map(normalizeGeneGlyph)
      .filter(Boolean)
      .join('');
  }

  private result(geneString: string): GeneRecognitionResult {
    return {
      geneString,
      confidence: 90,
      slotConfidences: [90, 90, 90, 90, 90, 90]
    };
  }
}
